/**
 * What every primitive of audio/ui shares and the kernel does not do: parts
 * named in kebab case, a value reported as `onValueChange` and
 * `onValueCommitted`, one pointer gesture at a time, and a native input
 * hidden from sight. The primitives import it from `../primitive`.
 */
import {
  bindDrag,
  type ChangeSource,
  createChange,
  definePrimitive as definePrimitiveOf,
  dispatch,
  type PointerSample,
  type PrimitiveContext,
} from "@ui-sdk/core";

/** A boolean as a data attribute: present and empty, or absent. */
export const flag = (on: boolean) => (on ? "" : undefined);

/** What a change reports to `onValueChange`, beside the value. */
export interface ChangeDetails {
  cancel: () => void;
  event?: Event;
  /** The point or segment that moved, for a control that has several. */
  index?: number;
  reason: string;
  source?: string;
}

/** What a commit reports to `onValueCommitted`, beside the value. */
export interface CommitDetails {
  event?: Event;
  index?: number;
  reason: string;
}

/** How a native input is hidden while it keeps the focus, the keys and the name. */
export const VISUALLY_HIDDEN = {
  border: "0",
  "clip-path": "inset(50%)",
  height: "1px",
  margin: "-1px",
  overflow: "hidden",
  padding: "0",
  position: "absolute",
  "white-space": "nowrap",
  width: "1px",
};

/**
 * How a change came about, when its event says. The kernel reads it from
 * input it tracks, so the first interaction would report "programmatic"
 * without this. With no event, the kernel decides, and an agent's change
 * stays the agent's.
 */
export function sourceOf(event?: Event): ChangeSource | undefined {
  if (typeof PointerEvent !== "undefined" && event instanceof PointerEvent) {
    return event.pointerType === "touch" || event.pointerType === "pen"
      ? event.pointerType
      : "mouse";
  }
  if (event instanceof MouseEvent) {
    return "mouse";
  }
  if (event instanceof KeyboardEvent) {
    return "keyboard";
  }
}

/** A change or a commit's details: the reason, the event, and who caused it when the event says. */
function detailsOf(reason: string, event?: Event, extra?: object) {
  const source = sourceOf(event);
  return { event, reason, ...(source ? { source } : {}), ...extra };
}

/**
 * How a primitive whose state holds a `value` reports it: `report` fires
 * `onValueChange` and keeps the value unless an app refused it, `commit`
 * fires `onValueCommitted`, and `setAtOnce` does both, for a change that is
 * over as soon as it is made (a key, a typed value, the wheel, a reset). It
 * skips a value `same` finds equal to the one `displayed` shows; with no
 * `same`, every value is reported, even an unchanged one. `extra` goes into
 * the details, such as the `index` of the point that moved.
 */
export function createReporter<State extends { value: Value }, Value>(
  context: PrimitiveContext<any, State, any>,
  displayed: (state: State) => Value,
  same?: (a: Value, b: Value) => boolean
) {
  const change = createChange(context);
  const state = () => context.store.get() as State;
  const commit = (
    value: Value,
    reason: string,
    event?: Event,
    extra?: object
  ) => {
    dispatch(
      context,
      "onValueCommitted",
      value,
      detailsOf(reason, event, extra)
    );
  };
  const report = (
    value: Value,
    reason: string,
    event?: Event,
    extra?: object
  ) =>
    change("value", value as never, detailsOf(reason, event, extra) as never);
  const setAtOnce = (
    value: Value,
    reason: string,
    event?: Event,
    extra?: object
  ) => {
    if (same?.(value, displayed(state()))) {
      return;
    }
    if (report(value, reason, event, extra)) {
      commit(value, reason, event, extra);
    }
  };
  return { commit, report, setAtOnce, state };
}

/** Two numbers as one text: a comma between them, or a semicolon where the comma is the decimal mark. */
export function formatPair(formatter: Intl.NumberFormat, a: number, b: number) {
  const decimalComma = formatter
    .formatToParts(1.5)
    .some((part) => part.type === "decimal" && part.value === ",");
  return `${formatter.format(a)}${decimalComma ? "; " : ", "}${formatter.format(b)}`;
}

/** Where in an interval a curve is checked against its chord, how many times an interval may be halved, and a ceiling on the vertices of one curve. */
const PROBES = [0.25, 0.5, 0.75];
const MAX_DEPTH = 8;
const MAX_SAMPLES = 4096;

/**
 * The vertices of a polyline that draws `f(t)` for `t` from 0 to 1 without
 * straying more than `tolerance` from it: it starts from `grid` and halves
 * every interval whose curve leaves its chord. `width` is how wide `t` from 0
 * to 1 spans in the box the curve is drawn in.
 */
export function adaptiveSamples(
  f: (t: number) => number,
  grid: readonly number[],
  tolerance: number,
  width = 1
) {
  const samples: [number, number][] = [];
  let budget = MAX_SAMPLES - grid.length;
  const refine = (
    from: number,
    start: number,
    to: number,
    end: number,
    depth: number
  ) => {
    if (depth >= MAX_DEPTH || budget <= 0) {
      return;
    }
    let stray = 0;
    let middle = Number.NaN;
    for (const probe of PROBES) {
      const value = f(from + (to - from) * probe);
      stray = Math.max(
        stray,
        Math.abs(value - (start + (end - start) * probe))
      );
      if (probe === 0.5) {
        middle = value;
      }
    }
    const slope = (end - start) / ((to - from) * width);
    if (stray / Math.sqrt(1 + slope * slope) <= tolerance) {
      return;
    }
    const half = (from + to) / 2;
    budget -= 1;
    refine(from, start, half, middle, depth + 1);
    samples.push([half, middle]);
    refine(half, middle, to, end, depth + 1);
  };
  const values = grid.map(f);
  grid.forEach((t, index) => {
    const value = values[index] ?? 0;
    samples.push([t, value]);
    const next = grid[index + 1];
    if (next !== undefined) {
      refine(t, value, next, values[index + 1] ?? 0, 0);
    }
  });
  return samples;
}

/**
 * What a change reports: why it happened (`reason`), the event behind it,
 * and `cancel()` to refuse the change.
 */
export interface ChangeEventDetails<Reason extends string, E extends Event> {
  cancel: () => void;
  event: E;
  readonly isCanceled: boolean;
  reason: Reason;
}

/** What a commit reports once a gesture ends: why it happened and the event behind it. */
export interface CommitEventDetails<Reason extends string, E extends Event> {
  event: E;
  reason: Reason;
}

/** The details of a change for `reason` and `event`, with `cancel()` to refuse it. */
export function createChangeEventDetails<
  Reason extends string,
  E extends Event,
>(reason: Reason, event: E): ChangeEventDetails<Reason, E> {
  let canceled = false;
  return {
    cancel: () => {
      canceled = true;
    },
    event,
    get isCanceled() {
      return canceled;
    },
    reason,
  };
}

/**
 * One pointer at a time on a control: while one drags, a press from another is
 * ignored, and the same pointer pressing again means its release was missed,
 * so the drag it left ends there. Moves arrive at most once per frame, each
 * with where the pointer was at the last one.
 */
export function createPointerLock() {
  type Held = {
    end: (event: PointerEvent) => void;
    pointerId: number;
    stop: () => void;
  };
  let held: Held | null = null;
  return {
    claim: (event: PointerEvent) => {
      if (!held) {
        return true;
      }
      if (held.pointerId !== event.pointerId) {
        return false;
      }
      const stale = held;
      held = null;
      stale.stop();
      stale.end(event);
      return true;
    },
    follow: (
      target: Element,
      down: PointerEvent,
      move: (event: PointerEvent, from: { x: number; y: number }) => void,
      end: (event: PointerEvent) => void
    ) => {
      let last = { x: down.clientX, y: down.clientY };
      const entry: Held = {
        end,
        pointerId: down.pointerId,
        stop: () => undefined,
      };
      held = entry;
      entry.stop = bindDrag(target as HTMLElement, down, {
        onEnd: (event) => {
          if (held === entry) {
            held = null;
          }
          end(event);
        },
        onMove: ({ event }) => {
          const from = last;
          last = { x: event.clientX, y: event.clientY };
          move(event, from);
        },
      });
    },
  };
}

/**
 * A value that changes outside the framework, in the shape of an external
 * store: `subscribe` registers a listener called on each change, and
 * `getSnapshot` returns the current value. What a primitive's `source` reads
 * from, so that following a signal costs no render.
 */
export interface Source<Value> {
  getSnapshot: () => Value;
  subscribe: (listener: () => void) => () => void;
}

/** A source that also takes values: what `createSource` returns. */
export interface WritableSource<Value> extends Source<Value> {
  /** Publishes a value. Subscribers are told every time, so the same array, updated in place, can be published again. */
  set: (value: Value) => void;
}

/**
 * A source you push to yourself, from an audio callback, a WebSocket, a worker
 * or a test: call `set` with each new reading, and whatever reads the source
 * follows.
 */
export function createSource<Value>(initial: Value): WritableSource<Value> {
  let value = initial;
  const listeners = new Set<() => void>();
  return {
    getSnapshot: () => value,
    set: (next) => {
      value = next;
      for (const listener of listeners) {
        listener();
      }
    },
    subscribe: (listener) => {
      listeners.add(listener);
      return () => {
        listeners.delete(listener);
      };
    },
  };
}

/** A value the primitive holds and its parts read outside any render. */
export interface Store<Value> {
  get: () => Value;
  set: (next: Value) => void;
  subscribe: (listener: () => void) => () => void;
}

/** A store holding `initial`: `set` tells every listener, unless the value is the same one. */
export function createStore<Value>(initial: Value): Store<Value> {
  let value = initial;
  const listeners = new Set<() => void>();
  return {
    get: () => value,
    set: (next) => {
      if (Object.is(next, value)) {
        return;
      }
      value = next;
      for (const listener of listeners) {
        listener();
      }
    },
    subscribe: (listener) => {
      listeners.add(listener);
      return () => listeners.delete(listener);
    },
  };
}

/** What a gesture hears, from the press that started it to its release. */
export interface GestureHandlers<Data> {
  /** The pointer lifted, or the browser took it over (`canceled`). */
  onEnd: (event: PointerEvent, data: Data, canceled: boolean) => void;
  /** At most once per frame, with the latest pointer event. */
  onMove: (event: PointerEvent, data: Data, sample: PointerSample) => void;
}

/**
 * A primitive's pointer gestures, one at a time. Call `accepts` first, before
 * the primitive's own guards: another pointer pressing while a gesture runs
 * is refused, so a second finger does not take the gesture over, and the
 * same pointer pressing again means its release was missed, so its gesture
 * ends there, through `onStale`. A gesture carries `data` of its own, read
 * back by `active`, and stops when the primitive is destroyed.
 */
export function createGestures<Data>(context: {
  onDestroy: (cleanup: () => void) => void;
}) {
  type Running = { data: Data; pointerId: number; stop: () => void };
  let running: Running | null = null;
  context.onDestroy(() => running?.stop());
  return {
    /** Whether `event` may start a gesture, ending a stale one of the same pointer first. */
    accepts(event: PointerEvent, onStale?: (data: Data) => void) {
      const stale = running;
      if (!stale) {
        return true;
      }
      if (stale.pointerId !== event.pointerId) {
        return false;
      }
      running = null;
      stale.stop();
      onStale?.(stale.data);
      return true;
    },
    /** The data of the gesture that runs, if any. */
    active: () => running?.data ?? null,
    /** Follows the press on `el` until it lifts. */
    start(
      el: HTMLElement,
      event: PointerEvent,
      data: Data,
      handlers: GestureHandlers<Data>
    ) {
      running?.stop();
      const entry: Running = {
        data,
        pointerId: event.pointerId,
        stop: () => undefined,
      };
      running = entry;
      entry.stop = bindDrag(el, event, {
        onEnd: (end, canceled) => {
          if (running === entry) {
            running = null;
          }
          handlers.onEnd(end, data, canceled);
        },
        onMove: (sample) => handlers.onMove(sample.event, data, sample),
      });
    },
  };
}

/** An element's box for one gesture, from `measuredBox`. */
export interface MeasuredBox {
  /** The box: measured the first time, and again only after the page scrolled or resized. */
  get: () => DOMRect;
  /** Stops watching the page. Call it when the gesture ends. */
  stop: () => void;
}

/**
 * An element's box, measured once for a gesture rather than on each of its
 * moves. Read after a move wrote to the page, `getBoundingClientRect` makes
 * the browser lay the page out on the spot, every frame. A scroll or a resize
 * during the gesture moves the element, so either one measures it again.
 */
export function measuredBox(element: Element): MeasuredBox {
  let box: DOMRect | null = null;
  const view = element.ownerDocument?.defaultView;
  const stale = () => {
    box = null;
  };
  view?.addEventListener("scroll", stale, { capture: true, passive: true });
  view?.addEventListener("resize", stale, { passive: true });
  return {
    get: () => {
      box ??= element.getBoundingClientRect();
      return box;
    },
    stop: () => {
      view?.removeEventListener("scroll", stale, { capture: true });
      view?.removeEventListener("resize", stale);
    },
  };
}

const KEBAB = /([a-z0-9])([A-Z])/g;
const kebab = (name: string) => name.replace(KEBAB, "$1-$2").toLowerCase();

/**
 * The part a primitive draws names itself in `data-slot`, in kebab case
 * (`xypad-input-x`, `piano-roll-note`), the names the styles and the docs
 * select: the kernel writes the slot's key as it is (`xypad-inputX`). A
 * component that gives its own name to a part (`timeline-time-selection`)
 * keeps it.
 */
function nameSlots(name: string, slots: Record<string, any>) {
  const prefix = kebab(name);
  for (const [key, definition] of Object.entries(slots)) {
    const fallback = key === "root" ? prefix : `${prefix}-${kebab(key)}`;
    const { attrs } = definition;
    definition.attrs = (state: unknown, context: { props?: object }) => ({
      ...attrs?.(state, context),
      "data-slot":
        (context.props as Record<string, string> | undefined)?.["data-slot"] ??
        fallback,
    });
    definition.props = { ...definition.props, "data-slot": "string" };
  }
  return slots;
}

/** `definePrimitive` of the kernel, with the parts named in kebab case and a `data-slot` that can be given. */
export const definePrimitive = ((options: any) =>
  definePrimitiveOf({
    ...options,
    slots: (slot: unknown) => nameSlots(options.name, options.slots(slot)),
  })) as typeof definePrimitiveOf;

/** The number a typed text means: "-6", "-6 dB" or "12,5". */
const typedNumber = (text: string) => {
  const parsed = Number.parseFloat(text.trim().replace(",", "."));
  return Number.isFinite(parsed) ? parsed : null;
};

const INPUT_STYLE =
  "position: absolute; inset: 0; width: 100%; height: 100%; margin: 0; padding: 0; border: 0; border-radius: inherit; background: inherit; color: inherit; font: inherit; text-align: center; box-sizing: border-box";

/**
 * Lets the reader type a value into a control's readout: a double click on
 * it, or Enter or F2 while it has focus, lays a text field over it. Enter or
 * leaving the field gives the control the number typed, through its native
 * range input, as a drag would; Escape keeps the value. The framework keeps
 * drawing the readout's text under the field. `root` is the control's slot
 * (`knob`, `fader`). Returns what takes it away.
 */
export function editableReadout(readout: HTMLElement, root: string) {
  let field: HTMLInputElement | null = null;
  const positioned = readout.style.position;
  const finish = (text: string | null) => {
    if (!field) {
      return;
    }
    field.remove();
    field = null;
    readout.removeAttribute("data-editing");
    readout.style.position = positioned;
    readout.focus({ preventScroll: true });
    const typed = text === null ? null : typedNumber(text);
    const input = readout
      .closest(`[data-slot="${root}"]`)
      ?.querySelector<HTMLInputElement>('input[type="range"]');
    if (typed === null || !input) {
      return;
    }
    Object.getOwnPropertyDescriptor(
      HTMLInputElement.prototype,
      "value"
    )?.set?.call(input, String(typed));
    input.dispatchEvent(new Event("input", { bubbles: true }));
    input.dispatchEvent(new Event("change", { bubbles: true }));
  };
  const open = () => {
    if (field || readout.closest("[data-disabled]")) {
      return;
    }
    const text = readout.textContent?.trim() ?? "";
    field = document.createElement("input");
    field.type = "text";
    field.inputMode = "decimal";
    field.value = text;
    field.size = Math.max(text.length, 3);
    field.style.cssText = INPUT_STYLE;
    const label = readout.getAttribute("aria-label");
    if (label) {
      field.setAttribute("aria-label", label);
    }
    field.addEventListener("keydown", (event) => {
      event.stopPropagation();
      if (event.key === "Enter") {
        event.preventDefault();
        finish(field?.value ?? null);
      } else if (event.key === "Escape") {
        event.preventDefault();
        finish(null);
      }
    });
    field.addEventListener("blur", () => finish(field?.value ?? null));
    if (getComputedStyle(readout).position === "static") {
      readout.style.position = "relative";
    }
    readout.setAttribute("data-editing", "");
    readout.appendChild(field);
    field.focus({ preventScroll: true });
    field.select();
  };
  // A readout inside a thumb or a control must not also reset or drag it.
  const handleDoubleClick = (event: MouseEvent) => {
    event.stopPropagation();
    open();
  };
  const handleKeyDown = (event: KeyboardEvent) => {
    if (
      event.target === readout &&
      (event.key === "Enter" || event.key === "F2")
    ) {
      event.preventDefault();
      open();
    }
  };
  const handlePointerDown = (event: PointerEvent) => event.stopPropagation();
  const tabIndex = readout.getAttribute("tabindex");
  readout.tabIndex = 0;
  readout.setAttribute("aria-keyshortcuts", "Enter");
  readout.setAttribute("data-editable", "");
  readout.addEventListener("dblclick", handleDoubleClick);
  readout.addEventListener("keydown", handleKeyDown);
  readout.addEventListener("pointerdown", handlePointerDown);
  return () => {
    finish(null);
    readout.removeEventListener("dblclick", handleDoubleClick);
    readout.removeEventListener("keydown", handleKeyDown);
    readout.removeEventListener("pointerdown", handlePointerDown);
    readout.removeAttribute("aria-keyshortcuts");
    readout.removeAttribute("data-editable");
    if (tabIndex === null) {
      readout.removeAttribute("tabindex");
    } else {
      readout.setAttribute("tabindex", tabIndex);
    }
  };
}

import {
  css,
  dispatch,
  type PrimitiveInstance,
  type PropSpec,
  type SlotDefinition,
} from "@ui-sdk/core";
import {
  clamp,
  fractionOf,
  type NumberScale,
  valueAt,
} from "@ui-sdk/core/number";
import {
  adaptiveSamples,
  createGestures,
  definePrimitive,
  flag,
  sourceOf,
  VISUALLY_HIDDEN,
} from "../primitive";

/**
 * The plot: a surface with two axes (a range and a scale each, linear or
 * logarithmic) on which curves, lines, bands, traces, dots, marks, a grid and
 * draggable handles are placed in the axes' units.
 *
 * Every part that draws is an `<svg>` of its own stretched over the plot (a
 * custom element cannot sit inside an `<svg>`): it exposes the path it draws in
 * its public state, and each framework writes it as the child. A live `source`
 * is painted straight onto that child, with no render.
 *
 * A handle is keyed by its `handle` name and holds a value of its own. What it
 * reports goes through the Root, `onValueChange` and `onValueCommitted`, with
 * the handle's name in the details.
 */

/** A point on the plot, in the axes' units. */
export interface PlotPoint {
  x: number;
  y: number;
}

/** The axes a handle moves along; the other keeps its value. */
export type PlotHandleAxis = "both" | "x" | "y";

/** A live value an engine pushes to: what it holds now, and a way to hear it change. */
export interface PlotSource<Value> {
  getSnapshot: () => Value;
  subscribe: (listener: () => void) => () => void;
}

/** One of the plot's two axes: its range and how values spread along it. */
export interface PlotAxis {
  max: number;
  min: number;
  scale: NumberScale;
}

/** A logarithmic axis needs a positive `min`; below that it spreads values evenly. */
const scaleOf = (axis: PlotAxis): NumberScale =>
  axis.scale === "log" && !(axis.min > 0 && axis.max > axis.min)
    ? "linear"
    : axis.scale;

/** Where `value` sits along `axis`, 0 at its `min` to 1 at its `max`. */
export const positionOn = (axis: PlotAxis, value: number) =>
  fractionOf(value, axis, scaleOf(axis));

/** The value at `position` (0 to 1) along `axis`. */
export const valueOn = (axis: PlotAxis, position: number) =>
  valueAt(position, axis, scaleOf(axis));

/** How far a drawn curve may stray from the function, as a share of the plot's height. */
const TOLERANCE = 0.0005;
/** How many ticks an axis gets unless asked for another number. */
const DEFAULT_TICK_COUNT = 5;
/** Candidates for a step's leading digit, in powers of ten. */
const STEP_MULTIPLES = [1, 2, 5, 10];
/** What an arrow key moves a handle by, as a share of the axis; Shift and Page Up/Down move ten times as far. */
const KEY_STEP = 0.01;
const LARGE_KEY_STEP = 0.1;
/** Shift slows a drag down to this share of the pointer's travel. */
const FINE_DRAG = 0.25;

const round = (value: number) => Math.round(value * 1e5) / 1e5;

/** The end of a path that closes down (or up) to `fillTo`, for a filled area. */
const closed = (path: string, y: PlotAxis, fillTo: number | undefined) => {
  if (fillTo === undefined) {
    return path;
  }
  const base = round(1 - positionOn(y, fillTo));
  return `${path} L 1 ${base} L 0 ${base} Z`;
};

/**
 * An SVG path drawing `y = fn(x)` across the whole x axis, in a 1 by 1 box
 * with y going up. Samples are spread evenly along the axis as drawn, so a
 * logarithmic axis gets as many per octave at the bottom as at the top, and
 * more are added where the curve bends tighter than that grid shows.
 */
function curvePath(
  fn: (x: number) => number,
  x: PlotAxis,
  y: PlotAxis,
  samples: number,
  fillTo?: number
) {
  const count = Math.max(2, Math.round(samples));
  const grid = Array.from({ length: count }, (_, index) => index / (count - 1));
  const height = (along: number) => {
    const value = fn(valueOn(x, along));
    return Number.isFinite(value) ? positionOn(y, value) : 0;
  };
  const points = adaptiveSamples(height, grid, TOLERANCE).map(
    ([along, up]) => `${round(along)} ${round(1 - up)}`
  );
  return closed(`M ${points.join(" L ")}`, y, fillTo);
}

/**
 * An SVG path through `values` spread evenly across the whole x axis, in the
 * same box: a spectrum, a level history. A value that is not a number sits on
 * the floor of the axis.
 */
function tracePath(values: ArrayLike<number>, y: PlotAxis, fillTo?: number) {
  if (values.length === 0) {
    return "";
  }
  const last = Math.max(values.length - 1, 1);
  const points: string[] = [];
  for (let index = 0; index < values.length; index += 1) {
    const value = values[index] ?? Number.NaN;
    const height = Number.isNaN(value) ? 0 : positionOn(y, value);
    points.push(`${round(index / last)} ${round(1 - height)}`);
  }
  return closed(`M ${points.join(" L ")}`, y, fillTo);
}

/** Even steps over `min` to `max`, at 1, 2 or 5 times a power of ten, roughly `count` of them. */
function linearTicks(min: number, max: number, count: number) {
  const span = max - min;
  if (!(span > 0 && count > 0)) {
    return [];
  }
  const raw = span / count;
  const power = 10 ** Math.floor(Math.log10(raw));
  const step =
    (STEP_MULTIPLES.find((multiple) => multiple * power >= raw) ?? 10) * power;
  const ticks: number[] = [];
  for (
    let value = Math.ceil(min / step) * step;
    value <= max + step * 1e-9;
    value += step
  ) {
    // Rounded to the step's own decimals, so 0.1 + 0.2 is 0.3.
    ticks.push(
      Number(value.toFixed(Math.max(0, -Math.floor(Math.log10(step)) + 1)))
    );
  }
  return ticks;
}

/** Ticks for a logarithmic axis: each power of ten, with its 2 and 5 when that still leaves room. */
function logTicks(min: number, max: number, count: number) {
  if (!(min > 0 && max > min)) {
    return [];
  }
  const decades = (multiples: readonly number[]) => {
    const ticks: number[] = [];
    for (
      let power = Math.floor(Math.log10(min));
      10 ** power <= max;
      power += 1
    ) {
      for (const multiple of multiples) {
        const value = multiple * 10 ** power;
        if (value >= min * (1 - 1e-9) && value <= max * (1 + 1e-9)) {
          ticks.push(value);
        }
      }
    }
    return ticks;
  };
  const fine = decades([1, 2, 5]);
  return fine.length <= count * 1.5 ? fine : decades([1]);
}

/** Round, evenly spread tick values for `axis`: by power of ten when it is logarithmic. */
const axisTicks = (axis: PlotAxis, count = DEFAULT_TICK_COUNT) =>
  axis.scale === "log"
    ? logTicks(axis.min, axis.max, count)
    : linearTicks(axis.min, axis.max, count);

const trim = (value: number) => String(Number(value.toFixed(2)));

/** A tick as short text: 1000 as "1k", 0.5 as "0.5", -12 as "-12". */
function formatTick(value: number) {
  const magnitude = Math.abs(value);
  if (magnitude >= 1_000_000) {
    return `${trim(value / 1_000_000)}M`;
  }
  if (magnitude >= 1000) {
    return `${trim(value / 1000)}k`;
  }
  return trim(value);
}

export interface PlotPrimitiveOptions {
  /** @default false */
  disabled?: boolean;
  /** @default 1 */
  maxX?: number;
  /** @default 1 */
  maxY?: number;
  /** @default 0 */
  minX?: number;
  /** @default 0 */
  minY?: number;
  /** A handle moved: its name is `details.handle`. `details.cancel()` refuses it. */
  onValueChange?: (value: PlotPoint, details: HandleChangeDetails) => void;
  /** A handle's gesture ended, or a key or input moved it. */
  onValueCommitted?: (value: PlotPoint, details: HandleCommitDetails) => void;
  /** How x values spread across: `"log"` for frequency, or a `{ to, from }` pair that maps values into an even space and back. @default "linear" */
  scaleX?: NumberScale;
  /** How y values spread up. @default "linear" */
  scaleY?: NumberScale;
}

/** What a handle's change reports. */
export interface HandleChangeDetails {
  cancel: () => void;
  event?: Event;
  /** The name of the handle that moved. */
  handle: string;
  reason: string;
  source?: string;
}

/** What a handle's commit reports. */
export interface HandleCommitDetails {
  event?: Event;
  handle: string;
  reason: string;
}

export interface PlotState {
  axes: { x: PlotAxis; y: PlotAxis };
  disabled: boolean;
  /** Counts the changes a handle made, so the parts read them again. */
  version: number;
}

/** What a part reads of the plot. */
export interface PlotPublicState {
  disabled: boolean;
}

/** A tick of a grid. */
export interface GridTick {
  label: string | null;
  /** 0 to 1 along the axis. */
  position: number;
  value: number;
}

/** What a grid draws along one axis. */
export interface GridAxis {
  /** About how many ticks to draw when they are not given. @default 5 */
  count?: number;
  /** Text for a tick's label. Defaults to a short number such as "1k". */
  format?: (value: number) => string;
  /** Whether the labels are written. @default true */
  labels?: boolean;
  /** Where the lines go. Without it, round values spread evenly over the axis. */
  ticks?: readonly number[];
}

/** What the grid draws. */
export interface GridState extends PlotPublicState {
  columns: GridTick[];
  rows: GridTick[];
}

/** What a part that draws a path reads: the path, in a 1 by 1 box with y going up. */
export interface PathState extends PlotPublicState {
  d: string;
}

/** What a line reads: its two ends, in the 1 by 1 box. */
export interface LineState extends PlotPublicState {
  x1: number;
  x2: number;
  y1: number;
  y2: number;
}

/** What a band reads: its box, in the 1 by 1 box. */
export interface BandState extends PlotPublicState {
  height: number;
  width: number;
  x: number;
  y: number;
}

/** What a handle reads of itself. */
export interface HandleState extends PlotPublicState {
  axis: PlotHandleAxis;
  /** Whether a pointer is dragging it. */
  dragging: boolean;
}

/** What a view draws a handle from. */
export interface PlotHandleSnapshot {
  axis: PlotHandleAxis;
  disabled: boolean;
  dragging: boolean;
  /** Where the handle sits along each axis, 0 to 1. */
  position: PlotPoint;
  /** The value, clamped to both axes. */
  value: PlotPoint;
}

/** A live value the plot writes and its parts read: the value under the pointer. */
interface WritableSource<Value> extends PlotSource<Value> {
  set: (value: Value) => void;
}

/** What a plot's `api` gives an adapter. */
export interface PlotApi {
  /** The latest value under the pointer, for a cursor readout. */
  cursor: WritableSource<PlotPoint | null>;
  /** What the handle named in `props` shows, with the latest props and axes. */
  handleView: (
    state: PlotState,
    props: HandleProps | HandleInputProps
  ) => PlotHandleSnapshot;
  /** Which key a `"key"` prop is keyed by. */
  internal: { keyOf: (handle: unknown) => string };
  /** Handles a key on a handle's input: arrows move a hundredth of the axis, Shift or Page Up/Down a tenth, Delete or Backspace reset. Returns whether it took the key. */
  keyDown: (name: string, event: KeyboardEvent) => boolean;
  /** The plot's box in the viewport; `fresh` reads it again, for the start of a gesture. */
  measure: (fresh?: boolean) => DOMRect | null;
  /** Starts a drag of a handle from where it is (Shift makes it four times finer); an Alt press resets it. */
  press: (name: string, event: PointerEvent, element: HTMLElement) => void;
  /** Returns a handle to its default value, reporting a `"reset"` change and commit. */
  reset: (name: string, event: Event) => void;
  /** The plot's element and what forgets its box, once it binds. */
  root: { el: HTMLElement | undefined; forget: () => void };
  /** Moves a handle along one axis to a position, 0 to 1, from an input. */
  typeAt: (
    name: string,
    along: "x" | "y",
    position: number,
    event: Event
  ) => void;
}

/** The props every part takes. */
interface PartProps {
  id?: string;
}

/** The props of a handle. */
export interface HandleProps extends PartProps {
  /** The axes it moves along; the other keeps the value given. @default "both" */
  axis?: PlotHandleAxis;
  defaultValue?: PlotPoint;
  disabled?: boolean;
  /** The name of the handle: what keys it and what its changes report. */
  handle: string;
  value?: PlotPoint;
}

/** The props of a handle's input for one axis. */
export interface HandleInputProps extends PartProps {
  /** Names the input. Defaults to the handle's `aria-label`, then "X" or "Y". */
  getAriaLabel?: (axis: "x" | "y") => string | undefined;
  /** Returns the input's `aria-valuetext`, from its value. */
  getAriaValueText?: (value: number, axis: "x" | "y") => string;
  handle: string;
}

/** The plot's slots, by name, with the props and the public state of each. */
export type PlotSlots = {
  band: SlotDefinition<
    PlotState,
    PlotApi,
    PartProps & { axis: "x" | "y"; from: number; to: number },
    BandState
  >;
  curve: SlotDefinition<
    PlotState,
    PlotApi,
    PartProps & {
      fillTo?: number;
      fn: (x: number) => number;
      samples?: number;
    },
    PathState
  >;
  cursor: SlotDefinition<PlotState, PlotApi, PartProps, PlotPublicState>;
  cursorReadout: SlotDefinition<
    PlotState,
    PlotApi,
    PartProps & { format: (value: PlotPoint) => string },
    object
  >;
  dot: SlotDefinition<
    PlotState,
    PlotApi,
    PartProps & { source?: PlotSource<PlotPoint>; value?: PlotPoint },
    PlotPublicState
  >;
  grid: SlotDefinition<
    PlotState,
    PlotApi,
    PartProps & { x?: GridAxis; y?: GridAxis },
    GridState
  >;
  handle: SlotDefinition<PlotState, PlotApi, HandleProps, HandleState>;
  inputX: SlotDefinition<PlotState, PlotApi, HandleInputProps, object>;
  inputY: SlotDefinition<PlotState, PlotApi, HandleInputProps, object>;
  line: SlotDefinition<
    PlotState,
    PlotApi,
    PartProps & { axis: "x" | "y"; value: number },
    LineState
  >;
  mark: SlotDefinition<
    PlotState,
    PlotApi,
    PartProps & { axis: "x" | "y"; value: number },
    PlotPublicState & { axis: "x" | "y" }
  >;
  root: SlotDefinition<PlotState, PlotApi, PartProps, PlotPublicState>;
  trace: SlotDefinition<
    PlotState,
    PlotApi,
    PartProps & {
      fillTo?: number;
      max?: number;
      min?: number;
      source: PlotSource<ArrayLike<number>>;
    },
    PathState
  >;
};

/**
 * The type of `plot`, written out: the kernel's own types its inferred type
 * would name are not exported, so a declaration could not print it.
 */
export interface PlotPrimitive {
  options: Record<string, PropSpec> | undefined;
  slots: PlotSlots;
  (
    initialOptions: PlotPrimitiveOptions & { id: string }
  ): Omit<PrimitiveInstance, "api" | "get" | "types"> & {
    api: PlotApi;
    get: () => PlotState;
    types: {
      api: PlotApi;
      options: PlotPrimitiveOptions;
      slots: PlotSlots;
      state: PlotState;
    };
  };
}

const axesOf = (options: PlotPrimitiveOptions) => ({
  x: {
    max: options.maxX ?? 1,
    min: options.minX ?? 0,
    scale: options.scaleX ?? "linear",
  },
  y: {
    max: options.maxY ?? 1,
    min: options.minY ?? 0,
    scale: options.scaleY ?? "linear",
  },
});

const stateOf = (options: PlotPrimitiveOptions): PlotState => ({
  axes: axesOf(options),
  disabled: options.disabled ?? false,
  version: 0,
});

const publicState = (state: PlotState): PlotPublicState => ({
  disabled: state.disabled,
});

/** Gives each function that reaches a curve an id, so a part that gets a new one is written again. */
const fnIds = new WeakMap<object, number>();
let nextFnId = 0;
const fnId = (value: unknown) => {
  if (
    value === null ||
    (typeof value !== "function" && typeof value !== "object")
  ) {
    return "0";
  }
  let id = fnIds.get(value);
  if (id === undefined) {
    nextFnId += 1;
    id = nextFnId;
    fnIds.set(value, id);
  }
  return String(id);
};

/** The box every drawing part is: an `<svg>` stretched over the plot, hidden from the pointer. */
const DRAWING_STYLE = {
  height: "100%",
  inset: "0",
  overflow: "visible",
  "pointer-events": "none",
  position: "absolute",
  width: "100%",
};

const drawingAttrs = (state: PlotState) => ({
  "aria-hidden": "true",
  "data-disabled": flag(state.disabled),
  preserveAspectRatio: "none",
  style: css(DRAWING_STYLE),
  viewBox: "0 0 1 1",
});

/** A drawing redrawn every frame, on a layer of its own: a frame repaints it alone, not the graph under it. */
const liveDrawingAttrs = (state: PlotState) => ({
  ...drawingAttrs(state),
  style: css({ ...DRAWING_STYLE, "will-change": "transform" }),
});

const percent = (value: number) =>
  `${(Number.isNaN(value) ? 0 : value) * 100}%`;

/** The path the framework wrote as the child of a drawing part: marked by the adapter. */
const PATH = 'path[data-plot="path"]';

/** Writes a path onto the child the framework made, if it is there yet. */
function paintPath(el: HTMLElement, d: string) {
  const path = el.querySelector(PATH);
  if (path && path.getAttribute("d") !== d) {
    path.setAttribute("d", d);
  }
}

const placement = (point: PlotPoint, axes: PlotState["axes"]) => ({
  left: percent(positionOn(axes.x, point.x)),
  top: percent(1 - positionOn(axes.y, point.y)),
});

/** A line at `value` along one axis, across the whole other. */
export const lineOf = (
  axes: PlotState["axes"],
  axis: "x" | "y",
  value: number
): Omit<LineState, "disabled"> => {
  const at =
    axis === "x" ? positionOn(axes.x, value) : 1 - positionOn(axes.y, value);
  return axis === "x"
    ? { x1: at, x2: at, y1: 0, y2: 1 }
    : { x1: 0, x2: 1, y1: at, y2: at };
};

/** A band from `from` to `to` along one axis, across the whole other. */
export const bandOf = (
  axes: PlotState["axes"],
  axis: "x" | "y",
  from: number,
  to: number
): Omit<BandState, "disabled"> => {
  const along = axis === "x" ? axes.x : axes.y;
  const start = round(positionOn(along, Math.min(from, to)));
  const end = round(positionOn(along, Math.max(from, to)));
  return axis === "x"
    ? { height: 1, width: round(end - start), x: start, y: 0 }
    : { height: round(end - start), width: 1, x: 0, y: round(1 - end) };
};

/** The ticks a grid draws along one axis. */
export const ticksOf = (
  axis: PlotAxis,
  options: GridAxis | undefined
): GridTick[] => {
  if (!options) {
    return [];
  }
  const values = options.ticks ?? axisTicks(axis, options.count);
  return values.map((value) => ({
    label:
      options.labels === false ? null : (options.format ?? formatTick)(value),
    position: positionOn(axis, value),
    value,
  }));
};

/** The path of a curve, in the 1 by 1 box with y going up: what a `curve` part draws. */
export const curveOf = (
  axes: PlotState["axes"],
  fn: (x: number) => number,
  samples?: number,
  fillTo?: number
) => curvePath(fn, axes.x, axes.y, samples ?? 256, fillTo);

/** The path of a trace of `values`: what a `trace` part draws. */
export const traceOf = (
  axes: PlotState["axes"],
  values: ArrayLike<number>,
  scale: { fillTo?: number; max?: number; min?: number } = {}
) =>
  tracePath(
    values,
    {
      max: scale.max ?? axes.y.max,
      min: scale.min ?? axes.y.min,
      scale: axes.y.scale,
    },
    scale.fillTo
  );

/** A source the plot writes itself. */
function createWritable<Value>(initial: Value): WritableSource<Value> {
  let value = initial;
  const listeners = new Set<() => void>();
  return {
    getSnapshot: () => value,
    set: (next) => {
      value = next;
      for (const listener of listeners) {
        listener();
      }
    },
    subscribe: (listener) => {
      listeners.add(listener);
      return () => listeners.delete(listener);
    },
  };
}

/** One drag of a handle, from press to release. */
interface HandleGesture {
  changed: boolean;
  fine: boolean;
  /** Where the handle was, as positions along each axis, when the drag began or Shift last changed. */
  origin: PlotPoint;
  /** The plot's box when the press began: it does not move under a drag. */
  rect: DOMRect | null;
  start: { x: number; y: number };
  /** The last value the drag applied, which its end commits. */
  value: PlotPoint | null;
}

/** What the plot keeps of one handle. */
interface HandleRecord {
  dragging: boolean;
  gestures: ReturnType<typeof createGestures<HandleGesture>>;
  /** The value as the gesture under way left it: a controlled value that lags behind must not pull the handle back mid-drag. */
  latest: PlotPoint | null;
  /** The props of the handle's newest render. */
  props: HandleProps;
  /** Held by the handle, unless its `value` is given. */
  uncontrolled: PlotPoint | undefined;
}

export const plot: PlotPrimitive = definePrimitive({
  api: (context) => {
    const state = () => context.store.get() as PlotState;
    const records = new Map<string, HandleRecord>();
    const root: PlotApi["root"] = { el: undefined, forget: () => undefined };
    let rect: DOMRect | null = null;
    root.forget = () => {
      rect = null;
    };
    const measure = (fresh = false) => {
      if (fresh || !rect) {
        const box = root.el?.getBoundingClientRect();
        rect = box && box.width > 0 && box.height > 0 ? box : null;
      }
      return rect;
    };
    const notify = () => context.store.set({ version: state().version + 1 });

    /** The handle of that name, told the props of its newest render. */
    const recordOf = (props: HandleProps | HandleInputProps) => {
      const name = String(props.handle);
      let record = records.get(name);
      if (!record) {
        record = {
          dragging: false,
          gestures: createGestures<HandleGesture>(context),
          latest: null,
          props: props as HandleProps,
          uncontrolled: undefined,
        };
        records.set(name, record);
      } else if ("value" in props || "axis" in props) {
        // The props take over again on every render of the handle itself.
        record.props = props as HandleProps;
        record.latest = null;
      }
      return record;
    };
    const byName = (name: string) => recordOf({ handle: name });

    const moves = (record: HandleRecord, along: "x" | "y") => {
      const axis = record.props.axis ?? "both";
      return axis === "both" || axis === along;
    };
    const disabledOf = (record: HandleRecord) =>
      state().disabled || Boolean(record.props.disabled);
    const clampPoint = (value: PlotPoint): PlotPoint => {
      const { axes } = state();
      return {
        x: valueOn(axes.x, positionOn(axes.x, value.x)),
        y: valueOn(axes.y, positionOn(axes.y, value.y)),
      };
    };
    const positionOf = (point: PlotPoint): PlotPoint => {
      const { axes } = state();
      return { x: positionOn(axes.x, point.x), y: positionOn(axes.y, point.y) };
    };
    const defaultPoint = (record: HandleRecord): PlotPoint => {
      const { axes } = state();
      return (
        record.props.defaultValue ?? {
          x: valueOn(axes.x, 0.5),
          y: valueOn(axes.y, 0.5),
        }
      );
    };
    /** The value the props or the handle hold: what a view shows. */
    const held = (record: HandleRecord) =>
      clampPoint(
        record.props.value ?? record.uncontrolled ?? defaultPoint(record)
      );
    /** The value as the gesture under way left it. */
    const current = (record: HandleRecord) => record.latest ?? held(record);

    /**
     * Clamps and proposes a value; keeps it unless refused, and returns the
     * value applied, or null. A commit reports that value: the handle may have
     * been drawn again, from props that lag, before it is made.
     */
    const change = (
      record: HandleRecord,
      next: PlotPoint,
      reason: string,
      event: Event
    ) => {
      const clamped = clampPoint(next);
      const now = current(record);
      if (clamped.x === now.x && clamped.y === now.y) {
        return null;
      }
      const source = sourceOf(event);
      const canceled = dispatch(context, "onValueChange", clamped, {
        event,
        handle: String(record.props.handle),
        reason,
        ...(source ? { source } : {}),
      });
      if (canceled) {
        return null;
      }
      record.latest = clamped;
      if (record.props.value === undefined) {
        record.uncontrolled = clamped;
      }
      notify();
      return clamped;
    };
    const commit = (
      record: HandleRecord,
      value: PlotPoint,
      reason: string,
      event: Event
    ) =>
      dispatch(context, "onValueCommitted", value, {
        event,
        handle: String(record.props.handle),
        reason,
      });

    /** Moves a handle to positions along each axis, 0 to 1, for the axes it moves along. */
    const moveTo = (
      record: HandleRecord,
      position: PlotPoint,
      reason: string,
      event: Event
    ) => {
      const { axes } = state();
      const now = current(record);
      return change(
        record,
        {
          x: moves(record, "x") ? valueOn(axes.x, position.x) : now.x,
          y: moves(record, "y") ? valueOn(axes.y, position.y) : now.y,
        },
        reason,
        event
      );
    };

    const reset = (record: HandleRecord, event: Event) => {
      if (disabledOf(record)) {
        return;
      }
      const target = positionOf(clampPoint(defaultPoint(record)));
      const applied = moveTo(record, target, "reset", event);
      if (applied) {
        commit(record, applied, "reset", event);
      }
    };

    const finish = (
      record: HandleRecord,
      gesture: HandleGesture,
      end: PointerEvent
    ) => {
      record.dragging = false;
      notify();
      if (gesture.changed) {
        commit(record, gesture.value ?? current(record), "drag", end);
      }
    };

    return {
      cursor: createWritable<PlotPoint | null>(null),
      handleView: (now: PlotState, props: HandleProps | HandleInputProps) => {
        const record = recordOf(props);
        const value = held(record);
        return {
          axis: record.props.axis ?? "both",
          disabled: now.disabled || Boolean(record.props.disabled),
          dragging: record.dragging,
          position: {
            x: positionOn(now.axes.x, value.x),
            y: positionOn(now.axes.y, value.y),
          },
          value,
        };
      },
      internal: { keyOf: (handle: unknown) => String(handle) },
      keyDown: (name: string, event: KeyboardEvent) => {
        const record = byName(name);
        if (disabledOf(record)) {
          return false;
        }
        if (event.key === "Delete" || event.key === "Backspace") {
          reset(record, event);
          return true;
        }
        const step = event.shiftKey ? LARGE_KEY_STEP : KEY_STEP;
        const at = positionOf(current(record));
        // Home and End go to the ends of the axis the handle moves along first.
        const ends = moves(record, "x") ? "x" : "y";
        const target = {
          ArrowDown: { x: at.x, y: at.y - step },
          ArrowLeft: { x: at.x - step, y: at.y },
          ArrowRight: { x: at.x + step, y: at.y },
          ArrowUp: { x: at.x, y: at.y + step },
          End: { ...at, [ends]: 1 },
          Home: { ...at, [ends]: 0 },
          PageDown: { x: at.x, y: at.y - LARGE_KEY_STEP },
          PageUp: { x: at.x, y: at.y + LARGE_KEY_STEP },
        }[event.key];
        if (!target) {
          return false;
        }
        const applied = moveTo(record, target, "keyboard", event);
        if (applied) {
          commit(record, applied, "keyboard", event);
        }
        return true;
      },
      measure,
      press: (name: string, event: PointerEvent, element: HTMLElement) => {
        const record = byName(name);
        if (
          disabledOf(record) ||
          event.button !== 0 ||
          !record.gestures.accepts(event, (stale) =>
            finish(record, stale, event)
          )
        ) {
          return;
        }
        // An Alt press returns to the default, as in a DAW.
        if (event.altKey) {
          reset(record, event);
          return;
        }
        const gesture: HandleGesture = {
          changed: false,
          fine: event.shiftKey,
          origin: positionOf(current(record)),
          rect: measure(true),
          start: { x: event.clientX, y: event.clientY },
          value: null,
        };
        record.dragging = true;
        notify();
        record.gestures.start(element, event, gesture, {
          onEnd: (end) => finish(record, gesture, end),
          onMove: (move) => {
            const box = gesture.rect;
            if (!box) {
              return;
            }
            // Shift pressed or let go mid-drag: carry on from here at the new speed.
            if (move.shiftKey !== gesture.fine) {
              gesture.fine = move.shiftKey;
              gesture.origin = positionOf(current(record));
              gesture.start = { x: move.clientX, y: move.clientY };
            }
            const speed = gesture.fine ? FINE_DRAG : 1;
            const along = {
              x:
                gesture.origin.x +
                ((move.clientX - gesture.start.x) / Math.max(box.width, 1)) *
                  speed,
              y:
                gesture.origin.y -
                ((move.clientY - gesture.start.y) / Math.max(box.height, 1)) *
                  speed,
            };
            const applied = moveTo(record, along, "drag", move);
            if (applied) {
              gesture.changed = true;
              gesture.value = applied;
            }
          },
        });
      },
      reset: (name: string, event: Event) => reset(byName(name), event),
      root,
      typeAt: (
        name: string,
        along: "x" | "y",
        position: number,
        event: Event
      ) => {
        const record = byName(name);
        const at = positionOf(current(record));
        const applied = moveTo(
          record,
          { ...at, [along]: position },
          "input-change",
          event
        );
        if (applied) {
          commit(record, applied, "input-change", event);
        }
      },
    };
  },
  name: "plot",
  options: {
    disabled: "boolean",
    maxX: "number",
    maxY: "number",
    minX: "number",
    minY: "number",
    onValueChange: "callback",
    onValueCommitted: "callback",
    scaleX: "value",
    scaleY: "value",
  },
  slots: (slot) => {
    const handleInput = (along: "x" | "y") =>
      slot<HandleInputProps>({
        attrs: (state: PlotState, { api, props }) => {
          const view = api.handleView(state, props);
          const current = view.value[along];
          return {
            "aria-label": props.getAriaLabel?.(along),
            "aria-orientation": along === "x" ? "horizontal" : "vertical",
            "aria-valuetext": props.getAriaValueText
              ? props.getAriaValueText(current, along)
              : String(Math.round(current * 100) / 100),
            disabled: flag(view.disabled),
            max: "1",
            min: "0",
            step: "any",
            style: css(VISUALLY_HIDDEN),
            // Only the first input is in the tab order.
            tabindex: along === "x" || view.axis === "y" ? undefined : "-1",
            type: "range",
            value: String(view.position[along]),
          };
        },
        on: {
          change: (event, { api, el, props }) =>
            api.typeAt(
              String(props.handle),
              along,
              Number((el as HTMLInputElement).value),
              event
            ),
          keydown: (event, { api, props }) => {
            if (api.keyDown(String(props.handle), event)) {
              event.preventDefault();
            }
          },
        },
        props: {
          getAriaLabel: "value",
          getAriaValueText: "value",
          handle: "key",
        },
      });

    return {
      band: slot<{ axis: "x" | "y"; from: number; to: number }, BandState>({
        attrs: drawingAttrs,
        props: { axis: "string", from: "number", to: "number" },
        state: (state: PlotState, { props }) => ({
          ...publicState(state),
          ...bandOf(state.axes, props.axis, props.from, props.to),
        }),
      }),
      curve: slot<
        { fillTo?: number; fn: (x: number) => number; samples?: number },
        PathState
      >({
        attrs: (state: PlotState, { props }) => ({
          ...drawingAttrs(state),
          "data-fill": flag(props.fillTo !== undefined),
          "data-fn": fnId(props.fn),
        }),
        props: { fillTo: "number", fn: "value", samples: "number" },
        state: (state: PlotState, { props }) => ({
          ...publicState(state),
          d: props.fn
            ? curveOf(state.axes, props.fn, props.samples, props.fillTo)
            : "",
        }),
      }),
      cursor: slot<object, PlotPublicState>({
        attrs: (state: PlotState) => ({
          "aria-hidden": "true",
          "data-disabled": flag(state.disabled),
          style: css({
            inset: "0",
            "pointer-events": "none",
            position: "absolute",
          }),
        }),
        // Follows the pointer over the plot, in the DOM: no render for a pointer that moves.
        bind: (el, part) => {
          // A child binds before its parent has set `root.el` or its attributes, in React and Vue: look for the plot once the parents have.
          let detach: () => void = () => undefined;
          let disposed = false;
          const listen = (plotEl: HTMLElement) => {
            const handleMove = (event: PointerEvent) => {
              if (event.pointerType === "touch") {
                return;
              }
              const box = part.api.measure();
              if (!box) {
                return;
              }
              const { axes } = part.store.get();
              const across = clamp(
                (event.clientX - box.left) / box.width,
                0,
                1
              );
              const down = clamp((event.clientY - box.top) / box.height, 0, 1);
              el.style.setProperty("--plot-cursor-x", `${across * 100}%`);
              el.style.setProperty("--plot-cursor-y", `${down * 100}%`);
              el.setAttribute("data-selected", "");
              part.api.cursor.set({
                x: valueOn(axes.x, across),
                y: valueOn(axes.y, 1 - down),
              });
            };
            const handleEnter = () => part.api.measure(true);
            const handleLeave = () => {
              el.removeAttribute("data-selected");
              part.api.cursor.set(null);
            };
            plotEl.addEventListener("pointerenter", handleEnter);
            plotEl.addEventListener("pointermove", handleMove);
            plotEl.addEventListener("pointerleave", handleLeave);
            return () => {
              plotEl.removeEventListener("pointerenter", handleEnter);
              plotEl.removeEventListener("pointermove", handleMove);
              plotEl.removeEventListener("pointerleave", handleLeave);
            };
          };
          queueMicrotask(() => {
            const plotEl = part.api.root.el ?? el.parentElement;
            if (disposed || !plotEl) {
              return;
            }
            detach = listen(plotEl);
          });
          return () => {
            disposed = true;
            detach();
          };
        },
        state: (state: PlotState) => publicState(state),
      }),
      cursorReadout: slot<{ format: (value: PlotPoint) => string }>({
        attrs: (state: PlotState) => ({
          "data-disabled": flag(state.disabled),
          style: css({
            left: "var(--plot-cursor-x)",
            position: "absolute",
            top: "var(--plot-cursor-y)",
          }),
        }),
        // One text node, rewritten in place as the pointer moves.
        bind: (el, part) => {
          const text = el.appendChild(document.createTextNode(""));
          const paint = () => {
            const value = part.api.cursor.getSnapshot();
            text.data = value ? part.props.format(value) : "";
          };
          paint();
          const off = part.api.cursor.subscribe(paint);
          return () => {
            off();
            text.remove();
          };
        },
        props: { format: "value" },
      }),
      dot: slot<
        { source?: PlotSource<PlotPoint>; value?: PlotPoint },
        PlotPublicState
      >({
        attrs: (state: PlotState, { props }) => {
          const point = props.source?.getSnapshot() ??
            props.value ?? { x: state.axes.x.min, y: state.axes.y.min };
          return {
            "aria-hidden": "true",
            "data-disabled": flag(state.disabled),
            style: css({
              ...placement(point, state.axes),
              "pointer-events": "none",
              position: "absolute",
              translate: "-50% -50%",
              // A live point moves every frame: on a layer of its own, its moves repaint nothing under it.
              ...(props.source ? { "will-change": "transform" } : {}),
            }),
          };
        },
        // A live point moves in the DOM, with no render.
        bind: (el, part) => {
          const { source } = part.props;
          if (!source) {
            return;
          }
          const paint = () => {
            const next = placement(source.getSnapshot(), part.store.get().axes);
            el.style.left = next.left;
            el.style.top = next.top;
          };
          paint();
          return source.subscribe(paint);
        },
        props: { source: "value", value: "value" },
        state: (state: PlotState) => publicState(state),
      }),
      grid: slot<{ x?: GridAxis; y?: GridAxis }, GridState>({
        attrs: (state: PlotState, { props }) => ({
          "aria-hidden": "true",
          "data-disabled": flag(state.disabled),
          // Changes when the ticks are given anew, so a part draws them again.
          "data-ticks": `${fnId(props.x)}.${fnId(props.y)}`,
          style: css({
            inset: "0",
            "pointer-events": "none",
            position: "absolute",
          }),
        }),
        props: { x: "value", y: "value" },
        state: (state: PlotState, { props }) => ({
          ...publicState(state),
          columns: ticksOf(state.axes.x, props.x),
          rows: ticksOf(state.axes.y, props.y),
        }),
      }),
      handle: slot<HandleProps, HandleState>({
        attrs: (state: PlotState, { api, props }) => {
          const view = api.handleView(state, props);
          return {
            "data-axis": view.axis,
            "data-disabled": flag(view.disabled),
            "data-dragging": flag(view.dragging),
            "data-handle": String(props.handle),
            style: css({
              left: `${view.position.x * 100}%`,
              position: "absolute",
              top: `${(1 - view.position.y) * 100}%`,
              "touch-action": "none",
              translate: "-50% -50%",
            }),
          };
        },
        on: {
          // A double click, or Alt with a press, brings the handle back to its default.
          dblclick: (event, { api, props }) =>
            api.reset(String(props.handle), event),
          pointerdown: (event, { api, el, props, store }) => {
            if (
              !el ||
              event.button !== 0 ||
              api.handleView(store.get(), props).disabled
            ) {
              return;
            }
            event.preventDefault();
            if (!event.altKey) {
              el.querySelector<HTMLInputElement>('input[type="range"]')?.focus({
                preventScroll: true,
              });
            }
            api.press(String(props.handle), event, el);
          },
        },
        props: {
          axis: "string",
          defaultValue: "value",
          disabled: "boolean",
          handle: "key",
          value: "value",
        },
        state: (state: PlotState, { api, props }) => {
          const view = api.handleView(state, props);
          return {
            axis: view.axis,
            disabled: view.disabled,
            dragging: view.dragging,
          };
        },
      }),
      inputX: handleInput("x"),
      inputY: handleInput("y"),
      line: slot<{ axis: "x" | "y"; value: number }, LineState>({
        attrs: drawingAttrs,
        props: { axis: "string", value: "number" },
        state: (state: PlotState, { props }) => ({
          ...publicState(state),
          ...lineOf(state.axes, props.axis, props.value),
        }),
      }),
      mark: slot<
        { axis: "x" | "y"; value: number },
        PlotPublicState & { axis: "x" | "y" }
      >({
        attrs: (state: PlotState, { props }) => ({
          "aria-hidden": "true",
          "data-axis": props.axis,
          "data-disabled": flag(state.disabled),
          style: css({
            ...(props.axis === "x"
              ? { left: percent(positionOn(state.axes.x, props.value)) }
              : { top: percent(1 - positionOn(state.axes.y, props.value)) }),
            "pointer-events": "none",
            position: "absolute",
          }),
        }),
        props: { axis: "string", value: "number" },
        state: (state: PlotState, { props }) => ({
          ...publicState(state),
          axis: props.axis,
        }),
      }),
      root: slot<object, PlotPublicState>({
        attrs: (state: PlotState) => ({
          "data-disabled": flag(state.disabled),
          // Layout containment: what moves inside the plot never makes the page around it lay out again.
          style: css({ contain: "layout style", position: "relative" }),
        }),
        bind: (el, part) => {
          part.api.root.el = el;
          const forget = () => part.api.root.forget();
          const observer =
            typeof ResizeObserver === "undefined"
              ? null
              : new ResizeObserver(forget);
          observer?.observe(el);
          window.addEventListener("scroll", forget, {
            capture: true,
            passive: true,
          });
          window.addEventListener("resize", forget, { passive: true });
          return () => {
            observer?.disconnect();
            window.removeEventListener("scroll", forget, { capture: true });
            window.removeEventListener("resize", forget);
            part.api.root.el = undefined;
          };
        },
        state: (state: PlotState) => publicState(state),
      }),
      trace: slot<
        {
          fillTo?: number;
          max?: number;
          min?: number;
          source: PlotSource<ArrayLike<number>>;
        },
        PathState
      >({
        // An area, filled to `fillTo`, says so: a sheet tells it from the line by it.
        attrs: (state: PlotState, { props }) => ({
          ...liveDrawingAttrs(state),
          "data-fill": flag(props.fillTo !== undefined),
        }),
        // A live trace is drawn straight onto its path, frame by frame.
        bind: (el, part) => {
          const { source } = part.props;
          if (!source) {
            return;
          }
          const paint = () =>
            paintPath(
              el,
              traceOf(part.store.get().axes, source.getSnapshot(), part.props)
            );
          paint();
          return source.subscribe(paint);
        },
        props: {
          fillTo: "number",
          max: "number",
          min: "number",
          source: "value",
        },
        state: (state: PlotState, { props }) => ({
          ...publicState(state),
          d: props.source
            ? traceOf(state.axes, props.source.getSnapshot(), props)
            : "",
        }),
      }),
    };
  },
  state: stateOf,
  sync: (options: PlotPrimitiveOptions) => {
    const { version: _version, ...held } = stateOf(options);
    return held;
  },
});

import { createParts } from "@ui-sdk/vue/primitive";
import { defineComponent, h } from "vue";
import {
  type BandState,
  type GridState,
  type HandleState,
  type LineState,
  type PathState,
  plot,
} from "./core";

/** Which element each part is. */
const parts = createParts(plot, {
  band: "svg",
  curve: "svg",
  cursor: "div",
  cursorReadout: "div",
  dot: "div",
  grid: "div",
  handle: "div",
  inputX: "input",
  inputY: "input",
  line: "svg",
  mark: "div",
  root: "div",
  trace: "svg",
});

/** A path that keeps its width however the plot is stretched. */
const NON_SCALING = { vectorEffect: "non-scaling-stroke" };

/** A part that draws one path: an `<svg>` over the plot, its path written as the child. */
const pathPart = (part: typeof parts.Curve, name: string) =>
  defineComponent(
    (_props, { attrs }) =>
      () =>
        h(part, attrs as never, {
          default: ({ state }: { state: PathState }) =>
            h("path", { d: state.d, "data-plot": "path", style: NON_SCALING }),
        }),
    { inheritAttrs: false, name }
  );

/** A curve across the plot: `y = fn(x)` in the axes' units. Style its `stroke` and `fill`. */
const Curve = pathPart(parts.Curve, "PlotCurve");

/** A live line across the plot, drawn straight in the DOM from a source. Style its `stroke` and `fill`. */
const Trace = pathPart(parts.Trace as never, "PlotTrace");

/** A straight line across the plot at a value. Style its `stroke`. */
const Line = defineComponent(
  (_props, { attrs }) =>
    () =>
      h(parts.Line, attrs as never, {
        default: ({ state }: { state: LineState }) =>
          h("line", {
            style: NON_SCALING,
            x1: state.x1,
            x2: state.x2,
            y1: state.y1,
            y2: state.y2,
          }),
      }),
  { inheritAttrs: false, name: "PlotLine" }
);

/** A stretch of the plot between two values on one axis. Style its `fill`. */
const Band = defineComponent(
  (_props, { attrs }) =>
    () =>
      h(parts.Band, attrs as never, {
        default: ({ state }: { state: BandState }) =>
          h("rect", {
            height: state.height,
            width: state.width,
            x: state.x,
            y: state.y,
          }),
      }),
  { inheritAttrs: false, name: "PlotBand" }
);

/** Grid lines and their labels: `data-part="line"` and `data-part="label"`, each with `data-axis`. */
const Grid = defineComponent(
  (_props, { attrs }) =>
    () =>
      h(parts.Grid, attrs as never, {
        default: ({ state }: { state: GridState }) => [
          h(
            "svg",
            {
              "aria-hidden": "true",
              height: "100%",
              preserveAspectRatio: "none",
              style: { inset: 0, overflow: "visible", position: "absolute" },
              viewBox: "0 0 1 1",
              width: "100%",
            },
            [
              ...state.columns.map((tick) =>
                h("line", {
                  "data-axis": "x",
                  "data-part": "line",
                  "data-zero": tick.value === 0 ? "" : undefined,
                  key: `x-${tick.value}`,
                  style: NON_SCALING,
                  x1: tick.position,
                  x2: tick.position,
                  y1: 0,
                  y2: 1,
                })
              ),
              ...state.rows.map((tick) =>
                h("line", {
                  "data-axis": "y",
                  "data-part": "line",
                  "data-zero": tick.value === 0 ? "" : undefined,
                  key: `y-${tick.value}`,
                  style: NON_SCALING,
                  x1: 0,
                  x2: 1,
                  y1: 1 - tick.position,
                  y2: 1 - tick.position,
                })
              ),
            ]
          ),
          ...state.columns
            .filter((tick) => tick.label !== null)
            .map((tick) =>
              h(
                "div",
                {
                  "data-axis": "x",
                  "data-part": "label",
                  key: `x-${tick.value}`,
                  style: {
                    left: `${tick.position * 100}%`,
                    position: "absolute",
                  },
                },
                tick.label ?? ""
              )
            ),
          ...state.rows
            .filter((tick) => tick.label !== null)
            .map((tick) =>
              h(
                "div",
                {
                  "data-axis": "y",
                  "data-part": "label",
                  key: `y-${tick.value}`,
                  style: {
                    position: "absolute",
                    top: `${(1 - tick.position) * 100}%`,
                  },
                },
                tick.label ?? ""
              )
            ),
        ],
      }),
  { inheritAttrs: false, name: "PlotGrid" }
);

/**
 * A point on the plot that can be moved, in the axes' units, with a native
 * `<input type="range">` for each axis it moves along carrying the names.
 */
const Handle = defineComponent(
  (
    props: {
      axis?: "both" | "x" | "y";
      getAriaLabel?: (axis: "x" | "y") => string | undefined;
      getAriaValueText?: (value: number, axis: "x" | "y") => string;
      handle: string;
    },
    { attrs, slots }
  ) =>
    () => {
      const { "aria-label": label, ...rest } = attrs;
      const axis = props.axis ?? "both";
      const nameOf = (along: "x" | "y") =>
        props.getAriaLabel?.(along) ??
        (label && axis === "both"
          ? `${label} ${along.toUpperCase()}`
          : (label as string | undefined));
      const input = (along: "x" | "y") =>
        h(along === "x" ? parts.InputX : parts.InputY, {
          getAriaLabel: nameOf,
          getAriaValueText: props.getAriaValueText,
          handle: props.handle,
        });
      return h(
        parts.Handle,
        { ...rest, axis, handle: props.handle },
        {
          default: (scope: { state: HandleState }) => [
            slots.default?.(scope),
            axis === "y" ? null : input("x"),
            axis === "x" ? null : input("y"),
          ],
        }
      );
    },
  {
    inheritAttrs: false,
    name: "PlotHandle",
    props: ["axis", "getAriaLabel", "getAriaValueText", "handle"],
  }
);

export const Plot = {
  Band,
  Curve,
  Cursor: parts.Cursor,
  CursorReadout: parts.CursorReadout,
  Dot: parts.Dot,
  Grid,
  Handle,
  Line,
  Mark: parts.Mark,
  Root: parts.Root,
  Trace,
};
